-- Where to learn a recipe, from this addon's own data (Data/Sources.lua = ns.Sources, generated by
-- dev/gen_sources.lua). UI/Sources.lua's Src.Build calls RecipeSources.Collect; the source rows, tooltip, menu
-- and waypoints stay there. No other addon is read. Every lookup is type-checked and every client call guarded.
local _, ns = ...
local W = { world = {} }
local G = _G -- CreateVector2D, UnitPosition, GetFactionInfoByID: client API not in .luacheckrc
ns.RecipeSources = W

local function Try(fn, ...)
  if type(fn) ~= "function" then return nil end
  local ok, a, b = pcall(fn, ...)
  if ok then return a, b end
  return nil
end

-- the bundled data, or nil
function W.DB()
  local db = ns.Sources
  if type(db) == "table" and type(db.recipes) == "table" and type(db.npcs) == "table" then return db end
  return nil
end

local SIDE = { Alliance = "A", Horde = "H" }
function W.Side()
  return SIDE[UnitFactionGroup and Try(UnitFactionGroup, "player") or ""]
end

local function Num01(v) return type(v) == "number" and v >= 0 and v <= 1 end

-- { id, name, side, zone?, level?, map?, x?, y? } of an NPC (map/x/y only when the data has real coordinates;
-- the zone name from the client, by map ID or area ID)
function W.NpcInfo(db, id)
  local row = type(id) == "number" and db.npcs[id]
  if type(row) ~= "table" or type(row[1]) ~= "string" then return nil end
  local n = { id = id, name = row[1], side = row[2] }
  if type(row[3]) == "number" and row[3] ~= 0 and Num01(row[4]) and Num01(row[5]) then n.map, n.x, n.y = row[3], row[4], row[5] end
  local zone = n.map and C_Map and Try(C_Map.GetMapInfo, n.map)
  if type(zone) == "table" then zone = zone.name
  elseif (tonumber(row[6]) or 0) > 0 and C_Map then zone = Try(C_Map.GetAreaInfo, row[6]) end
  if type(zone) == "string" and zone ~= "" then n.zone = zone end
  local lv = type(db.levels) == "table" and db.levels[id]
  if type(lv) == "table" and tonumber(lv[1]) and tonumber(lv[2]) then
    n.level = lv[1] == lv[2] and tostring(lv[1]) or (lv[1] .. "-" .. lv[2])
  end
  return n
end
local NpcInfo = W.NpcInfo

-- your side can deal with this NPC ("" = both sides; "X" or unknown = nobody)
local function Usable(n, side) return n.side == "" or (side ~= nil and n.side == side) end

-- squared distance on your continent; huge on another one or without a position (world position cached per NPC)
function W.Distance(n)
  local w = W.world[n.id]
  if w == nil then
    w = false
    if n.map and C_Map and C_Map.GetWorldPosFromMapPos and G.CreateVector2D then
      local ok, inst, x, y = pcall(function()
        local i, pos = C_Map.GetWorldPosFromMapPos(n.map, G.CreateVector2D(n.x, n.y))
        return i, pos:GetXY()
      end)
      if ok and inst and x and y then w = { inst, x, y } end
    end
    W.world[n.id] = w
  end
  if not (w and G.UnitPosition) then return math.huge end
  local ok, px, py, _, inst = pcall(G.UnitPosition, "player")
  if not (ok and px and py) or inst ~= w[1] then return math.huge end
  return (px - w[2]) ^ 2 + (py - w[3]) ^ 2
end

-- the nearest of these NPCs your side can use (ties and none on your continent: the earlier one in the list);
-- nobody usable (creatures, the other side only): the first in the list
function W.NearestNpc(db, ids, side)
  if type(ids) ~= "table" or type(ids[1]) ~= "number" then return nil end
  local best, bestD = nil, math.huge
  for _, id in ipairs(ids) do
    local n = NpcInfo(db, id)
    if n and Usable(n, side) then
      local d = W.Distance(n)
      if not best or d < bestD then best, bestD = n, d end
    end
  end
  return best or NpcInfo(db, ids[1])
end
local NearestNpc = W.NearestNpc

-- trainers of a profession who teach the rank of `level` (rank bits 1 / 2 / 4 / 8 up to 75 / 150 / 225 / 300)
function W.Trainers(db, prof, level)
  local rank = level <= 75 and 1 or level <= 150 and 2 or level <= 225 and 4 or 8
  local out = {}
  local list = type(db.trainers) == "table" and db.trainers[prof]
  for _, row in ipairs(type(list) == "table" and list or {}) do
    if type(row) == "table" and math.floor((tonumber(row[2]) or 0) / rank) % 2 == 1 then out[#out + 1] = row[1] end
  end
  return out
end

-- your standing with a faction (1 hated ... 4 neutral ... 8 exalted; neutral when the client doesn't know it) + its name
function W.Standing(id)
  local d = C_Reputation and Try(C_Reputation.GetFactionDataByID, id)
  if type(d) == "table" and tonumber(d.reaction) then return d.reaction, d.name end
  if G.GetFactionInfoByID then
    local ok, name, _, st = pcall(G.GetFactionInfoByID, id)
    if ok and tonumber(st) then return st, name end
  end
  return 4, nil
end

local function Secret(v) return ns.GCA and ns.GCA.IsSecret and ns.GCA.IsSecret(v) end
local function StandingName(n)
  local v = type(n) == "number" and _G["FACTION_STANDING_LABEL" .. n]
  if type(v) == "string" and v ~= "" and not Secret(v) then return v end
  return tostring(n)
end
local function FactionName(db, id)
  local _, name = W.Standing(id)
  if type(name) == "string" and name ~= "" and not Secret(name) then return name end
  local en = type(db.factions) == "table" and db.factions[id]
  return type(en) == "string" and en or ("#" .. tostring(id))
end

-- Adds the recipe's sources to info.list (trainer, quests, vendor incl. Merchant's Favor, drop / world drop /
-- chests) and sets info.scroll / info.rep. info.skill is our required skill. false: the data doesn't know it.
function W.Collect(info, prof, spellID)
  local db = W.DB()
  local r = db and db.recipes[spellID]
  if type(r) ~= "table" then return false end
  local list, side = info.list, W.Side()
  if r.t then
    local skill = (info.skill or 0) > 0 and info.skill or 1
    list[#list + 1] = { kind = "trainer", cost = tonumber(r.fee), npc = NearestNpc(db, W.Trainers(db, prof, skill), side) }
  end
  info.scroll = tonumber(r.s)
  if info.scroll then
    for _, qid in ipairs(type(r.q) == "table" and r.q or {}) do
      local q = type(db.quests) == "table" and db.quests[qid]
      if type(q) == "table" and type(q[1]) == "string" and (q[2] == "" or q[2] == side) then
        list[#list + 1] = { kind = "quest", name = q[1], level = tonumber(q[3]), npc = NearestNpc(db, q[4], side) }
      end
    end
    if type(r.v) == "table" and r.v[1] then
      local usable = {}
      for _, id in ipairs(r.v) do
        local n = NpcInfo(db, id)
        if n and Usable(n, side) then usable[#usable + 1] = id end
      end
      local s = { kind = "vendor", cost = tonumber(r.p), favor = tonumber(r.fv), count = #usable }
      s.npc = NearestNpc(db, usable, side)
      s.otherSide = s.npc == nil
      list[#list + 1] = s
    end
    if type(r.d) == "table" and type(r.d[1]) == "number" then
      local s = { kind = "drop", count = #r.d, npc = NearestNpc(db, r.d, side), npcs = {} }
      for i = 1, math.min(#r.d, 6) do s.npcs[#s.npcs + 1] = NpcInfo(db, r.d[i]) end
      s.npc = s.npc or s.npcs[1]
      if s.npc then list[#list + 1] = s end -- creatures the data can't name: no "Drop: ?" line
    elseif tonumber(r.w) then
      local lv = type(r.wl) == "table" and tonumber(r.wl[1]) and tonumber(r.wl[2]) and r.wl or nil
      list[#list + 1] = { kind = "world", count = tonumber(r.w), levels = lv }
    elseif tonumber(r.o) then
      list[#list + 1] = { kind = "objects", count = tonumber(r.o) }
    end
  end
  if type(r.rep) == "table" and tonumber(r.rep[1]) and tonumber(r.rep[2]) then
    info.rep = { standing = StandingName(r.rep[2]), name = FactionName(db, r.rep[1]), met = (W.Standing(r.rep[1])) >= r.rep[2] }
  end
  return true
end

return W
